from __future__ import annotations

import hashlib
import json
import unicodedata

GENESIS = "GENESIS"


def normalize_key(s: str) -> str:
    return unicodedata.normalize("NFC", s)


def canonical_bytes(line: dict) -> bytes:
    return json.dumps(
        line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def line_hash(prev_hash: str, line: dict) -> str:
    emptied = {k: v for k, v in line.items() if k not in ("hash", "prev_hash")}
    payload = prev_hash.encode("utf-8") + b"|" + canonical_bytes(emptied)
    return hashlib.sha256(payload).hexdigest()

