    """Raised when a mutation targets a key already committed under a different rid."""

    def __init__(self, key, incoming_rid, committed_rid, batch_index=None):
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        super().__init__(
            "conflict on key {!r}: incoming rid {!r} vs committed rid {!r}".format(
                key, incoming_rid, committed_rid
            )
        )


class Ledger:
    def __init__(self, path):
        self.path = os.fspath(path)

    def append(self, operation):
        return append(self, operation)

    def verify(self):
        return verify(self)

    def snapshot(self):
        return snapshot(self)

    def apply_batch(self, operations):
        return apply_batch(self, operations)


def append(ledger, operation):
    _, fields, key, rid = _parse_operation(operation)

    _, _, key_map = _read_state(ledger.path)

    existing = key_map.get(key)
    if existing is not None:
        committed_rid = existing["id"]
        if rid == committed_rid:
            result = dict(existing)
            result["replayed"] = True
            result["committed"] = False
            return result
        raise ConflictError(
            key=key, incoming_rid=rid, committed_rid=committed_rid, batch_index=None
        )

    prev_hash = _tail_hash(ledger.path)
    fields["prev_hash"] = prev_hash
    fields["hash"] = fmt.line_hash(prev_hash, fields)

    line_bytes = fmt.canonical_bytes(fields) + b"\n"
    _append_bytes(ledger.path, line_bytes)

    result = dict(fields)
    result["replayed"] = False
    result["committed"] = True
    return result


def verify(ledger):
    lines = store.read_lines(ledger.path)
    prev = fmt.GENESIS
    for i, raw in enumerate(lines):
        obj = json.loads(raw.decode("utf-8"))
        stored_prev = obj.get("prev_hash")
        stored_hash = obj.get("hash")
        if not isinstance(stored_prev, str) or not isinstance(stored_hash, str):
            return {"ok": False, "first_bad_index": i}
        if fmt.line_hash(stored_prev, obj) != stored_hash:
            return {"ok": False, "first_bad_index": i}
        if stored_prev != prev:
            return {"ok": False, "first_bad_index": i}
        prev = stored_hash
    return {"ok": True, "first_bad_index": None}


def snapshot(ledger):
    try:
        lines = store.read_lines(ledger.path)
    except FileNotFoundError:
        return {}
    state = {}
    for raw in lines:
        try:
            obj = json.loads(raw.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            break
        key = obj.get("key")
        if key is None:
            continue
        if obj.get("op") == "put":
            state[key] = obj.get("value")
        elif obj.get("op") == "delete":
            state.pop(key, None)
    return dict(sorted(state.items()))


