    raw_lines, last, key_map = _read_state(ledger.path)

    tail_hash = last["hash"] if last is not None else fmt.GENESIS
    new_lines = []
    appended = []

    for i, operation in enumerate(operations):
        _, fields, key, rid = _parse_operation(operation)

        existing = key_map.get(key)
        if existing is not None:
            committed_rid = existing["id"]
            if rid == committed_rid:
                continue
            raise ConflictError(
                key=key, incoming_rid=rid, committed_rid=committed_rid, batch_index=i
            )

        fields["prev_hash"] = tail_hash
        fields["hash"] = fmt.line_hash(tail_hash, fields)
        tail_hash = fields["hash"]

        key_map[key] = fields
        appended.append(dict(fields))
        new_lines.append(fmt.canonical_bytes(fields) + b"\n")

    if new_lines:
        store.write_atomic(ledger.path, raw_lines + new_lines)

    return appended


